// Общие шаги для «Closed date/time» работы (#94c08102). Сессия и язык — из address-helpers.ts / plans-helpers.ts.
import { expect, Locator, Page } from '@playwright/test';

export const JOB_STATUSES = ['Submitted', 'Assigned', 'Pending', 'In Progress', 'Awaiting Approval', 'Completed', 'Cancelled'];

/** Работы, закрытые до появления поля (комментарий программиста: у старых — «-»). */
export const OLD_COMPLETED_JOBS = ['JOB-0013', 'JOB-0011', 'JOB-0010', 'JOB-0003'];

/** /jobs → вкладка статуса (EN «Completed», HE «הסתיימו»). */
export async function openJobsTab(page: Page, tabName: string) {
  await page.goto('/jobs');
  await expect(page.locator('main')).toContainText('JOB-00');
  await page.getByRole('tab', { name: tabName, exact: true }).click();
  await expect(page.getByRole('tab', { name: tabName, exact: true })).toHaveAttribute('aria-selected', 'true');
}

export const jobRow = (page: Page, jobId: string): Locator => page.locator('tr', { hasText: jobId }).first();

/** Job Details: выпадающий список статуса (EN). */
export const statusSelect = (page: Page): Locator =>
  page.getByRole('combobox').filter({ hasText: new RegExp(`^(${JOB_STATUSES.join('|')})$`) }).first();

/** Значение «Closed: …» на странице работы (EN). */
export const closedValue = (page: Page): Locator =>
  page.locator('div').filter({ has: page.getByText('Closed:', { exact: true }) }).last().locator('span').last();

/**
 * Сменить статус на странице работы. При Completed может открыться «Complete Job?» (если в компании включён
 * auto_invoice) — подтверждаем: счёт создаётся только при первом закрытии (повторно — нет, код JobDetail).
 */
export async function setJobStatus(page: Page, status: string) {
  await statusSelect(page).click();
  await page.getByRole('option', { name: status, exact: true }).click();
  if (status === 'Completed') {
    const confirmDlg = page.getByRole('alertdialog').filter({ hasText: 'Complete Job?' });
    const closed = page.getByText('Closed:', { exact: true });
    await expect(confirmDlg.or(closed).first()).toBeVisible({ timeout: 20_000 });
    if (await confirmDlg.isVisible()) await confirmDlg.getByRole('button', { name: 'Confirm', exact: true }).click();
  }
  await expect(statusSelect(page)).toHaveText(status);
}

/** «Oct 14, 2026, 1:53 PM» → Date (локальное время браузера = время раннера). */
export function parseClosed(text: string): Date {
  const d = new Date(text.replace(/\s+/g, ' ').trim());
  expect(Number.isNaN(d.getTime()), `не дата: «${text}»`).toBe(false);
  return d;
}
